  "team.value-accuracy-desc": { en: "We ensure every piece of information is verified and up to date.", rw: "Tumenya ko buri kantu k'amakuru gahwemewe kandi kagezweho.", fr: "Nous veillons à ce que chaque information soit vérifiée et à jour.", sw: "Tunahakikisha kila taarifa imethibitishwa na imesasishwa.", ar: "نضمن أن كل معلومة موثقة ومحدثة." },
  "team.value-accessibility": { en: "Accessibility", rw: "Kuboneka", fr: "Accessibilité", sw: "Ufikiaji", ar: "سهولة الوصول" },
  "team.value-accessibility-desc": { en: "Our platform is free and open to all students.", rw: "Urubuga rwacu ni ubuntu kandi rufunguye ku banyeshuri bose.", fr: "Notre plateforme est gratuite et ouverte à tous les étudiants.", sw: "Jukwaa letu ni bure na wazi kwa wanafunzi wote.", ar: "منصتنا مجانية ومفتوحة لجميع الطلاب." },
  "team.value-integrity": { en: "Integrity", rw: "Kwirinda", fr: "Intégrité", sw: "Uadilifu", ar: "النزاهة" },
  "team.value-integrity-desc": { en: "We operate with transparency and honesty in everything we do.", rw: "Dukora mu mucyo no mu kuri mu byo dukora byose.", fr: "Nous opérons avec transparence et honnêteté dans tout ce que nous faisons.", sw: "Tunafanya kazi kwa uwazi na uaminifu katika kila tunachofanya.", ar: "نعمل بشفافية وأمانة في كل ما نقوم به." },
  "team.value-innovation": { en: "Innovation", rw: "Ihaza", fr: "Innovation", sw: "Ubunifu", ar: "الابتكار" },
